const KEY='kitchenAccountingRecordsV1',PKEY='kitchenAccountingProductsV2',DKEY='kitchenAccountingDeletedIdsV1',DMKEY='kitchenAccountingDeletedAtV1';try{localStorage.removeItem('kitchenAccountingNormsV1')}catch(e){}let records=readStore(KEY,[]),products=readStore(PKEY,[]),deletedIds=readStore(DKEY,[]),deletedAt=readStore(DMKEY,{}),editing=null; if(!Array.isArray(records))records=[];if(!Array.isArray(products))products=[];if(!Array.isArray(deletedIds))deletedIds=[];deletedIds=deletedIds.map(String);if(!deletedAt||typeof deletedAt!=='object'||Array.isArray(deletedAt))deletedAt={};const $=id=>document.getElementById(id);
function persist(){try{localStorage.setItem(KEY,JSON.stringify(records));localStorage.setItem(PKEY,JSON.stringify(products));localStorage.setItem(DKEY,JSON.stringify(deletedIds));localStorage.setItem(DMKEY,JSON.stringify(deletedAt))}catch(e){alert('Не удалось сохранить данные на устройстве. Проверь свободное место и разрешение на хранение данных. Ошибка: '+e.message);return false}renderAll();scheduleGoogleSync?.();return true}

function updateProducts(){$('productOptions').innerHTML=products.slice().sort((a,b)=>a.localeCompare(b,'ru')).map(p=>'<option value="'+esc(p)+'">').join('');}
function calc(){let pieceTotal=(Number($('steaks').value)||0)*(Number($('unitWeight').value)||0),plan=(Number($('layout1').value)||0),actual=(Number($('actualYield').value)||0)+pieceTotal,diff=actual-plan,pct=plan>0?diff/plan*100:0;$('yieldDeviation').textContent=(diff>0?'+':'')+kg(diff)+' кг ('+(plan>0?(pct>0?'+':'')+pct.toLocaleString('ru-RU',{maximumFractionDigits:1}):'0')+'%)';$('yieldDeviation').className=diff<-.0005?'bad':diff>.0005?'good':''}['actualYield','layout1','steaks','unitWeight'].forEach(id=>$(id).addEventListener('input',calc));let lastAutoProductKey='';$('product').addEventListener('input',()=>{applyTechCardPlan();calc()});
function resetForm(){$('recordForm').reset();$('stamp').value=nowLocal();$('steaks').value='';$('unitWeight').value='';$('layout1').value='';$('actualYield').value='';editing=null;lastAutoProductKey='';resetTechCardScale();$('formTitle').textContent='Новая обработка';$('saveBtn').textContent='Сохранить обработку';$('cancelEdit').classList.add('hidden');calc()}
$('recordForm').addEventListener('submit',e=>{e.preventDefault();let product=$('product').value.trim(),actualYield=Number($('actualYield').value),steaks=Number($('steaks').value)||0,plannedYield=Number($('layout1').value);if(!product)return alert('Укажите продукт.');if(!Number.isFinite(actualYield)||actualYield<0)return alert('Укажите фактический выход — неотрицательное число.');if(!Number.isFinite(plannedYield)||plannedYield<0||!Number.isFinite(steaks)||steaks<0||!Number.isInteger(steaks))return alert('Плановый и фактический выход, а также количество должны быть неотрицательными; количество — целым числом.');const productKey=product.replace(/\s+/g,' ').toLocaleLowerCase('ru-RU');const existingProduct=products.find(p=>String(p).trim().replace(/\s+/g,' ').toLocaleLowerCase('ru-RU')===productKey);if(existingProduct)product=String(existingProduct).trim();else products.push(product);let unitWeight=Number($('unitWeight').value)||0;if(!Number.isFinite(unitWeight)||unitWeight<0)return alert('Вес одной штуки должен быть неотрицательным числом.');const previousRecord=editing?records.find(x=>String(x.id)===String(editing)):null;let techCardScale=buildTechCardScaleSnapshot();if(!techCardScale&&previousRecord&&normalizeTechProductName(previousRecord.product)===normalizeTechProductName(product))techCardScale=previousRecord.techCardScale||null;let r={id:editing||crypto.randomUUID(),product,steaks,unitWeight,layout1:plannedYield,layout2:0,layout3:0,layout4:0,plannedYield,actualYield,yield:actualYield,stamp:$('stamp').value,comment:$('comment').value.trim(),techCardScale,updatedAt:versionNow()};if(editing)records=records.map(x=>x.id===editing?r:x);else records.push(r);if(!persist())return;resetForm();$('filterDate').value='';switchTab('journal')});
